export const getRevokePerformanceVerificationUrl = (performanceId: string,) => {




  return `/api/performance-records/${performanceId}/revoke`
}

/**
 * @summary Revoke a verification and remove its claims from public display
 */
export const revokePerformanceVerification = async (performanceId: string,
    revokePerformanceInput: RevokePerformanceInput, options?: Parameters<typeof customFetch>[1]): Promise<PerformanceRecord> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<PerformanceRecord>(getRevokePerformanceVerificationUrl(performanceId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(revokePerformanceInput)
  }
);}





